  function readerOnboarding(e){const selected=agent().arc.r===e.id,readOnly=catalogState.readOnly||!selected;return `<section class="dossier-section" data-reader-section="onboarding">${readerHeading(3,'入职问题','ONBOARDING')}${(e.onboarding_questions||[]).map((q,i)=>`<div class="field dossier-question"><label for="catalog-reality-${e.id}-${i}"><span class="mono">0${i+1}</span>${h(q)}</label><textarea id="catalog-reality-${e.id}-${i}" rows="2" maxlength="8000" ${readOnly?'disabled':`data-reality-answer="${i}"`}>${h(selected?agent().realityAnswers[i]||'':'')}</textarea></div>`).join('')}</section>`;}
  function readerBody(k,e){let body=readerOverview(k,e);if(k==='a')return body+e.abilities.map((a,i)=>`<section class="dossier-section dossier-ability" data-reader-section="ability-${i+1}">${readerHeading(i+1,a.name,'ANOMALY / ABILITY',a.quality)}<div class="dossier-trigger"><span>触发</span><p>${readerText(a.trigger)}</p></div><div class="dossier-results">${readerResult('success','成功',a.success)}${readerResult('bonus','追加',bonusText(a))}${readerResult('failure','失败',a.failure)}</div><small class="dossier-source mono">手册 ${a.source?.printed_page||e.page+1} 页</small></section>`).join('');if(k==='r'){const marks=agent().arc.r===e.id?agent().realityMarks:0;return body+`<section class="dossier-section" data-reader-section="trigger">${readerHeading(1,'现实触发器','REALITY / TRIGGER')}<h4 class="dossier-statement">${h(e.trigger.name)}</h4><p class="dossier-rule">${readerText(e.trigger.text)}${e.trigger.connection_penalty?`<br>${h(e.trigger.connection_penalty.relationship_selector)}失去 <b class="rule-emphasis">${e.trigger.connection_penalty.amount} 连结</b>。`:''}</p>${e.track?`<div class="dossier-track"><h4>${h(e.track.name)}</h4>${TA_DOSSIER.trackBoxes(e.track.boxes,marks,{label:e.track.name})}<p>${readerText(e.track.mark_when)}<br>${readerText(e.track.transition)}</p></div>`:''}${(e.special_rules||[]).map(t=>`<p class="dossier-rule">${readerText(t)}</p>`).join('')}</section><section class="dossier-section" data-reader-section="relief">${readerHeading(2,'过载解除','OVERLOAD / RELIEF')}<h4 class="dossier-statement">${h(e.release.name)}</h4><p class="dossier-rule">${readerText(e.release.text)}</p></section>${readerOnboarding(e)}<section class="dossier-section" data-reader-section="relationships">${readerHeading(4,'关系矩阵','RELATIONSHIP / MATRIX')}<div class="dossier-relationships">${e.relationships.map((q,i)=>`<article><span class="mono">0${i+1}</span><p>${h(q.question)}</p>${agent().arc.r===e.id&&agent().relationships[i]?.name?`<strong>${h(agent().relationships[i].name)}</strong>`:''}</article>`).join('')}</div></section>`;}const violation=typeof e.prime_directive.violation==='string'?e.prime_directive.violation:e.prime_directive.violation.options.join(' / ');return body+`<section class="dossier-section" data-reader-section="directive">${readerHeading(1,'首要指令','PRIME / DIRECTIVE')}<h4 class="dossier-statement">${h(e.prime_directive.text)}</h4><div class="dossier-violation"><span>违例</span><p>${h(violation)}</p><strong>+1 申诫</strong></div></section><section class="dossier-section" data-reader-section="behaviors">${readerHeading(2,'许可行为','SANCTIONED / BEHAVIOR')}<div class="dossier-behaviors">${e.sanctioned_behaviors.map((text,i)=>`<div><span class="mono">0${i+1}</span><p>${h(text)}</p><b>+1</b></div>`).join('')}</div></section><section class="dossier-section" data-reader-section="requisition">${readerHeading(3,'初始申领物','INITIAL / REQUISITION')}<h4 class="dossier-statement">${h(e.initial_requisition.name)}</h4><p class="dossier-rule">${readerText(e.initial_requisition.text)}</p></section>`;}
  function readerNavigation(k,e){return `<span class="jump-heading mono">INDEX / ${k.toUpperCase()}</span><div class="jump-links"><i class="jump-marker" aria-hidden="true"></i>${TA_CATALOG.readerSections(k,e).map((row,i)=>`<button data-reader-jump="${row.id}" data-reader-view="${row.view}" class="jump-button" aria-label="${h(row.label)}"><span class="jump-number mono">${String(i).padStart(2,'0')}</span><span class="jump-label">${h(row.label)}</span></button>`).join('')}</div><i class="jump-track" aria-hidden="true"><i></i></i>`;}
  function catalogViewTabs(k,e){if(!TA_CATALOG.hasExtra(k,e))return '';return `<nav class="catalog-view-tabs" aria-label="${labels[k]}内容"><button data-catalog-view="detail" aria-label="详解" class="${catalogState.view==='detail'?'active':''}" aria-pressed="${catalogState.view==='detail'}">详解</button><button data-catalog-view="extra" aria-label="${k==='c'?'评估':'角色细节'}" class="${catalogState.view==='extra'?'active':''}" aria-pressed="${catalogState.view==='extra'}">${k==='c'?'评估':'角色细节'}<i class="catalog-required-dot" aria-label="有未填项" hidden></i></button></nav>`;}
