    change(`选择${labels[k]}：${e.name}`,()=>{agent().arc[k]=e.id;agent().completed=false;if(k==='c'){agent().answers=[null,null,null];agent().qaMax=E.blankQA();agent().qa=E.blankQA();agent().qaGrowth=E.blankQA();agent().directiveChoice=null;agent().mission.equipmentUsed=false;}if(k==='r'){agent().realityMarks=0;agent().realityAnswers=['','',''];}if(k==='a')agent().practiced=[];for(const key of Object.keys(agent().arcDetails))if(key.startsWith(k+':'))delete agent().arcDetails[key];});renderCatalogDetail();return true;
