  function counter(resource,value,kind='resource'){const label=Q.find(q=>q.id===resource)?.name||({commendations:'嘉奖',demerits:'申诫',burnout:'额外过载',chaos:'共享混沌',damage:'伤害',extraOverload:'情境过载',extraThrees:'额外的3'}[resource])||agent().relationships[Number(resource)]?.name||'数值';return`<span class="counter"><button data-${kind}="${h(resource)}:-1" aria-label="减少${h(label)}">−</button><output>${value}</output><button data-${kind}="${h(resource)}:1" aria-label="增加${h(label)}">+</button></span>`;}
  function qaRows(){return officialQualities({interactive:true});}
