  function abilityCard(ability,index,expanded=false){return`<article class="ability-card" data-live-key="ability:${h(ability.id)}"><div class="ability-head"><div class="ability-name"><span class="ability-index mono">0${index+1}</span><div><h3>${h(ability.name)}</h3><small>${h(ability.quality)}${agent().practiced.includes(ability.id)?' / 已熟练':''}</small></div></div><div class="ability-actions"><button class="icon-button" data-ability-detail="${ability.id}" aria-label="查阅${h(ability.name)}">${icon('book')}</button><button class="ability-start" data-ability-roll="${ability.id}">发动${icon('arrow')}</button></div></div><p class="ability-trigger">${h(ability.trigger)}</p>${expanded?`<div class="ability-details">${abilityDetails(ability)}</div>`:''}</article>`;}
  function renderPlay(){return playQuick?TA_MISSION_VIEW.quick(agent(),E,quickDraft||newQuickDraft()):agent().activeMission?renderOperations():TA_MISSION_VIEW.hub(agent());}
  function newQuickDraft(){return{name:'',deltas:{commendations:0,demerits:0,burnout:0},chaos:0,connections:{},summary:'',award:null};}
