  function openMissionStart(){if(agent().activeMission){playQuick=false;render();return;}openSheet(`${modalHead('执行任务','MISSION / INITIALIZE')}<form id="mission-start-form"><div class="field large"><label for="mission-name">任务名称</label><input id="mission-name" maxlength="120" required autocomplete="off" placeholder="输入本次任务名称"></div><div class="modal-actions"><button class="primary-button" type="submit">进入外勤执行 →</button></div></form>`);}
